#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_fully_connected_s8(const cmsis_nn_context *ctx,
                                           const cmsis_nn_fc_params *fc_params,
                                           const cmsis_nn_per_tensor_quant_params *quant_params,
                                           const cmsis_nn_dims *input_dims,
                                           const int8_t *input,
                                           const cmsis_nn_dims *filter_dims,
                                           const int8_t *kernel,
                                           const cmsis_nn_dims *bias_dims,
                                           const int32_t *bias,
                                           const cmsis_nn_dims *output_dims,
                                           int8_t *output)
{
    (void)bias_dims;

    int32_t batch_cnt = input_dims->n;

    const int32_t *kernel_sum = (const int32_t *)ctx->buf;

    (void)kernel_sum;
    ime_fc_s8(input, filter_dims->n, batch_cnt, kernel, output_dims->c, filter_dims->n,
              fc_params->input_offset, fc_params->filter_offset, bias,
              &quant_params->multiplier, &quant_params->shift, 0,
              fc_params->output_offset, fc_params->activation.min, fc_params->activation.max, output, output_dims->c);
    return (ARM_CMSIS_NN_SUCCESS);
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_convolve_1x1_s8_fast(const cmsis_nn_context *ctx,
                                             const cmsis_nn_conv_params *conv_params,
                                             const cmsis_nn_per_channel_quant_params *quant_params,
                                             const cmsis_nn_dims *input_dims,
                                             const int8_t *input_data,
                                             const cmsis_nn_dims *filter_dims,
                                             const int8_t *filter_data,
                                             const cmsis_nn_dims *bias_dims,
                                             const int32_t *bias_data,
                                             const cmsis_nn_dims *output_dims,
                                             int8_t *output_data)
{
    if (conv_params->padding.w != 0 || conv_params->padding.h != 0 || conv_params->stride.w != 1 ||
        conv_params->stride.h != 1)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }

    (void)filter_dims;
    (void)bias_dims;

    const int32_t rhs_cols = input_dims->c;
    const int32_t rhs_rows = output_dims->c;
    int32_t lhs_rows = input_dims->w * input_dims->h * input_dims->n;

    (void)ctx;

    ime_fc_s8(input_data, rhs_cols, lhs_rows, filter_data, rhs_rows, rhs_cols,
              conv_params->input_offset, 0, bias_data, quant_params->multiplier, quant_params->shift, 1,
              conv_params->output_offset, conv_params->activation.min, conv_params->activation.max, output_data, rhs_rows);

    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_batch_matmul_s8(const cmsis_nn_context *ctx,
                                        const cmsis_nn_bmm_params *bmm_params,
                                        const cmsis_nn_per_tensor_quant_params *quant_params,
                                        const cmsis_nn_dims *input_lhs_dims,
                                        const int8_t *input_lhs,
                                        const cmsis_nn_dims *input_rhs_dims,
                                        const int8_t *input_rhs,
                                        const cmsis_nn_dims *output_dims,
                                        int8_t *output)
{
    (void)ctx;

    const int32_t output_batch = output_dims->n;
    const int32_t output_height = output_dims->h;
    const int32_t lhs_rows = input_lhs_dims->w;
    const int32_t rhs_rows = input_rhs_dims->w;
    const int32_t rhs_cols = input_rhs_dims->c;

    const int32_t inner_lhs_diff = input_lhs_dims->h >= input_rhs_dims->h ? 0 : lhs_rows * rhs_cols;
    const int32_t inner_rhs_diff = input_rhs_dims->h >= input_lhs_dims->h ? rhs_rows * rhs_cols : 0;
    const int32_t outer_lhs_diff = input_lhs_dims->n >= input_rhs_dims->n
        ? inner_lhs_diff
        : -((lhs_rows * rhs_cols) - inner_lhs_diff) * input_lhs_dims->h;
    const int32_t outer_rhs_diff = input_rhs_dims->n >= input_lhs_dims->n ? (rhs_rows * rhs_cols) - inner_rhs_diff
                                                                          : -inner_rhs_diff * input_rhs_dims->h;

    for (int i_out_batch = 0; i_out_batch < output_batch; i_out_batch++)
    {
        for (int i_out_height = 0; i_out_height < output_height; i_out_height++)
        {

            ime_fc_s8(input_lhs, rhs_cols, lhs_rows, input_rhs, rhs_rows, rhs_cols,
                      bmm_params->fc_params.input_offset, bmm_params->fc_params.filter_offset, NULL,
                      &quant_params->multiplier, &quant_params->shift, 0, bmm_params->fc_params.output_offset,
                      bmm_params->fc_params.activation.min, bmm_params->fc_params.activation.max, output, rhs_rows);
            input_lhs += lhs_rows * rhs_cols;
            output += lhs_rows * rhs_rows;
            input_lhs -= inner_lhs_diff;
            input_rhs += inner_rhs_diff;
        }
        input_lhs += outer_lhs_diff;
        input_rhs += outer_rhs_diff;
    }

    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


static arm_cmsis_nn_status arm_convolve_s8_ref(const cmsis_nn_context *ctx,
                                    const cmsis_nn_conv_params *conv_params,
                                    const cmsis_nn_per_channel_quant_params *quant_params,
                                    const cmsis_nn_dims *input_dims,
                                    const int8_t *input_data,
                                    const cmsis_nn_dims *filter_dims,
                                    const int8_t *filter_data,
                                    const cmsis_nn_dims *bias_dims,
                                    const int32_t *bias_data,
                                    const cmsis_nn_dims *upscale_dims,
                                    const cmsis_nn_dims *output_dims,
                                    int8_t *output_data)
{
    (void)bias_dims;

    if (ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int16_t *buffer_a = (int16_t *)ctx->buf;

    const int32_t input_batches = input_dims->n;
    const uint16_t input_x = input_dims->w;
    const uint16_t input_y = input_dims->h;
    const uint16_t input_ch = input_dims->c;
    const uint16_t kernel_x = filter_dims->w;
    const uint16_t kernel_y = filter_dims->h;
    const uint16_t kernel_ch = filter_dims->c;
    const uint16_t output_x = output_dims->w;
    const uint16_t output_y = output_dims->h;
    const uint16_t output_ch = output_dims->c;

    const uint16_t pad_x = conv_params->padding.w;
    const uint16_t pad_y = conv_params->padding.h;
    const uint16_t stride_x = conv_params->stride.w;
    const uint16_t stride_y = conv_params->stride.h;
    const int32_t dilation_x = conv_params->dilation.w;
    const int32_t dilation_y = conv_params->dilation.h;
    const int32_t out_offset = conv_params->output_offset;
    const int32_t out_activation_min = conv_params->activation.min;
    const int32_t out_activation_max = conv_params->activation.max;
    const int32_t input_offset = conv_params->input_offset;

    const int32_t groups = input_ch / kernel_ch;
    const int32_t rhs_cols = kernel_x * kernel_y * kernel_ch;
    const int32_t output_ch_per_group = output_ch / groups;

    const int32_t *output_mult = quant_params->multiplier;
    const int32_t *output_shift = quant_params->shift;

    if (input_ch % groups != 0 || output_ch % groups != 0)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }

    uint32_t y_rshift = 0;
    uint32_t x_rshift = 0;

    if (upscale_dims)
    {
        y_rshift = upscale_dims->h == 2 ? 1 : 0;
        x_rshift = upscale_dims->w == 2 ? 1 : 0;
    }

    const int32_t input_x_rshifted = input_x >> x_rshift;
    const int32_t input_y_rshifted = input_y >> y_rshift;

    const int32_t remainder = rhs_cols % 4;
    const int32_t aligned_rhs_cols = remainder != 0 ? rhs_cols + 4 - remainder : rhs_cols;

    for (int i_batch = 0; i_batch < input_batches; i_batch++)
    {

        int8_t *im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
        int16_t *im2col_buf_start_s16 = buffer_a;

        int32_t lhs_rows = 0;

        const int8_t *filter_data_ptr = &filter_data[0];
        const int32_t *bias_data_ptr = &bias_data[0];
        const int32_t *output_mult_ptr = &output_mult[0];
        const int32_t *output_shift_ptr = &output_shift[0];

        for (int32_t i_group = 0; i_group < groups; i_group++)
        {
            int8_t *out = output_data + i_group * output_ch_per_group;
            for (int i_out_y = 0; i_out_y < output_y; i_out_y++)
            {
                for (int i_out_x = 0; i_out_x < output_x; i_out_x++)
                {
                    const int32_t base_idx_x = stride_x * i_out_x - pad_x;
                    const int32_t base_idx_y = stride_y * i_out_y - pad_y;

                    if (y_rshift == 1 || x_rshift == 1)
                    {

                        arm_memset_s8(
                            im2col_buf, (int8_t)-input_offset, sizeof(int8_t) * kernel_ch * kernel_x * kernel_y);
                        for (int32_t i_ker_y = 0; i_ker_y < kernel_y; i_ker_y++)
                        {
                            const int32_t k_y = base_idx_y + dilation_y * i_ker_y;

                            if ((k_y < 0 || k_y >= input_y) || (k_y % 2 && y_rshift == 1))
                            {
                                im2col_buf += kernel_ch * kernel_x;
                            }
                            else
                            {
                                const int32_t k_y_rshifted = k_y >> y_rshift;
                                for (int32_t i_ker_x = 0; i_ker_x < kernel_x; i_ker_x++)
                                {
                                    const int32_t k_x = base_idx_x + dilation_x * i_ker_x;

                                    if ((k_x >= 0 && k_x < input_x) && ((k_x % 2 == 0) || x_rshift == 0))
                                    {
                                        const int32_t k_x_rshifted = k_x >> x_rshift;
                                        arm_memcpy_s8(im2col_buf,
                                                      input_data +
                                                          (k_y_rshifted * input_x_rshifted + k_x_rshifted) * input_ch,
                                                      sizeof(int8_t) * kernel_ch);
                                    }
                                    im2col_buf += kernel_ch;
                                }
                            }
                        }
                    }
                    else
                    {
                        for (int32_t i_ker_y = 0; i_ker_y < kernel_y; i_ker_y++)
                        {
                            for (int32_t i_ker_x = 0; i_ker_x < kernel_x; i_ker_x++)
                            {
                                const int32_t k_y = base_idx_y + dilation_y * i_ker_y;
                                const int32_t k_x = base_idx_x + dilation_x * i_ker_x;

                                if (k_y < 0 || k_y >= input_y || k_x < 0 || k_x >= input_x)
                                {
                                    arm_memset_s8(im2col_buf, (int8_t)-input_offset, sizeof(int8_t) * kernel_ch);
                                }
                                else
                                {
                                    arm_memcpy_s8(im2col_buf,
                                                  input_data + (k_y * input_x + k_x) * input_ch + i_group * kernel_ch,
                                                  sizeof(int8_t) * kernel_ch);
                                }
                                im2col_buf += kernel_ch;
                            }
                        }
                    }
                    lhs_rows++;

                    arm_q7_to_q15_with_offset(
                        im2col_buf - rhs_cols, im2col_buf_start_s16, rhs_cols, (int16_t)input_offset);

                    im2col_buf_start_s16 += aligned_rhs_cols;

                    if (lhs_rows == 2)
                    {
                        if (groups > 1)
                        {
                            out = arm_nn_mat_mult_kernel_row_offset_s8_s16(filter_data_ptr,
                                                                           buffer_a,
                                                                           output_ch_per_group,
                                                                           output_shift_ptr,
                                                                           output_mult_ptr,
                                                                           out_offset,
                                                                           out_activation_min,
                                                                           out_activation_max,
                                                                           rhs_cols,
                                                                           aligned_rhs_cols,
                                                                           bias_data_ptr,
                                                                           output_ch,
                                                                           out);
                        }
                        else
                        {
                            out = arm_nn_mat_mult_kernel_s8_s16(filter_data_ptr,
                                                                buffer_a,
                                                                output_ch_per_group,
                                                                output_shift_ptr,
                                                                output_mult_ptr,
                                                                out_offset,
                                                                out_activation_min,
                                                                out_activation_max,
                                                                rhs_cols,
                                                                aligned_rhs_cols,
                                                                bias_data_ptr,
                                                                out);
                        }

                        im2col_buf_start_s16 = buffer_a;
                        im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
                        lhs_rows = 0;
                    }

                }
            }

            if (out == NULL)
            {
                return ARM_CMSIS_NN_NO_IMPL_ERROR;
            }

            if (lhs_rows != 0)
            {

                const int8_t *ker_a = filter_data_ptr;
                int i;

                for (i = 0; i < output_ch_per_group; i++)
                {

                    int32_t sum = 0;
                    if (bias_data_ptr)
                    {
                        sum = bias_data_ptr[i];
                    }

                    const int16_t *ip_as_col = buffer_a;

                    uint16_t col_count = rhs_cols;

                    while (col_count)
                    {
                        int8_t ker_a1 = *ker_a++;
                        int16_t ip_b1 = *ip_as_col++;

                        sum += ker_a1 * ip_b1;
                        col_count--;
                    }

                    sum = arm_nn_requantize(sum, output_mult_ptr[i], output_shift_ptr[i]);
                    sum += out_offset;
                    sum = MAX(sum, out_activation_min);
                    sum = MIN(sum, out_activation_max);
                    *out++ = (int8_t)sum;
                }

                im2col_buf_start_s16 = buffer_a;
                im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
                lhs_rows = 0;

            }
            filter_data_ptr += output_ch_per_group * rhs_cols;
            bias_data_ptr += output_ch_per_group;
            output_mult_ptr += output_ch_per_group;
            output_shift_ptr += output_ch_per_group;
        }

        input_data += (input_x_rshifted * input_y_rshifted * input_ch);
        output_data += (output_x * output_y * output_ch);
    }

    return ARM_CMSIS_NN_SUCCESS;
}

arm_cmsis_nn_status arm_convolve_s8(const cmsis_nn_context *ctx,
                                    const cmsis_nn_conv_params *conv_params,
                                    const cmsis_nn_per_channel_quant_params *quant_params,
                                    const cmsis_nn_dims *input_dims,
                                    const int8_t *input_data,
                                    const cmsis_nn_dims *filter_dims,
                                    const int8_t *filter_data,
                                    const cmsis_nn_dims *bias_dims,
                                    const int32_t *bias_data,
                                    const cmsis_nn_dims *upscale_dims,
                                    const cmsis_nn_dims *output_dims,
                                    int8_t *output_data)
{
    if (ctx->buf == NULL)
        return ARM_CMSIS_NN_ARG_ERROR;
    if (upscale_dims && (upscale_dims->h == 2 || upscale_dims->w == 2))
        return arm_convolve_s8_ref(ctx, conv_params, quant_params, input_dims, input_data, filter_dims, filter_data,
                                   bias_dims, bias_data, upscale_dims, output_dims, output_data);
    if (input_dims->c % filter_dims->c != 0 || output_dims->c % (input_dims->c / filter_dims->c) != 0)
        return ARM_CMSIS_NN_ARG_ERROR;
    (void)bias_dims;
    ime_conv_s8(conv_params, quant_params, input_dims, input_data, filter_dims, filter_data, bias_data, output_dims,
                output_data);
    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


static arm_cmsis_nn_status arm_convolve_s8_ref(const cmsis_nn_context *ctx,
                                    const cmsis_nn_conv_params *conv_params,
                                    const cmsis_nn_per_channel_quant_params *quant_params,
                                    const cmsis_nn_dims *input_dims,
                                    const int8_t *input_data,
                                    const cmsis_nn_dims *filter_dims,
                                    const int8_t *filter_data,
                                    const cmsis_nn_dims *bias_dims,
                                    const int32_t *bias_data,
                                    const cmsis_nn_dims *upscale_dims,
                                    const cmsis_nn_dims *output_dims,
                                    int8_t *output_data)
{
    (void)bias_dims;

    if (ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int16_t *buffer_a = (int16_t *)ctx->buf;

    const int32_t input_batches = input_dims->n;
    const uint16_t input_x = input_dims->w;
    const uint16_t input_y = input_dims->h;
    const uint16_t input_ch = input_dims->c;
    const uint16_t kernel_x = filter_dims->w;
    const uint16_t kernel_y = filter_dims->h;
    const uint16_t kernel_ch = filter_dims->c;
    const uint16_t output_x = output_dims->w;
    const uint16_t output_y = output_dims->h;
    const uint16_t output_ch = output_dims->c;

    const uint16_t pad_x = conv_params->padding.w;
    const uint16_t pad_y = conv_params->padding.h;
    const uint16_t stride_x = conv_params->stride.w;
    const uint16_t stride_y = conv_params->stride.h;
    const int32_t dilation_x = conv_params->dilation.w;
    const int32_t dilation_y = conv_params->dilation.h;
    const int32_t out_offset = conv_params->output_offset;
    const int32_t out_activation_min = conv_params->activation.min;
    const int32_t out_activation_max = conv_params->activation.max;
    const int32_t input_offset = conv_params->input_offset;

    const int32_t groups = input_ch / kernel_ch;
    const int32_t rhs_cols = kernel_x * kernel_y * kernel_ch;
    const int32_t output_ch_per_group = output_ch / groups;

    const int32_t *output_mult = quant_params->multiplier;
    const int32_t *output_shift = quant_params->shift;

    if (input_ch % groups != 0 || output_ch % groups != 0)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }

    uint32_t y_rshift = 0;
    uint32_t x_rshift = 0;

    if (upscale_dims)
    {
        y_rshift = upscale_dims->h == 2 ? 1 : 0;
        x_rshift = upscale_dims->w == 2 ? 1 : 0;
    }

    const int32_t input_x_rshifted = input_x >> x_rshift;
    const int32_t input_y_rshifted = input_y >> y_rshift;

    const int32_t remainder = rhs_cols % 4;
    const int32_t aligned_rhs_cols = remainder != 0 ? rhs_cols + 4 - remainder : rhs_cols;

    for (int i_batch = 0; i_batch < input_batches; i_batch++)
    {

        int8_t *im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
        int16_t *im2col_buf_start_s16 = buffer_a;

        int32_t lhs_rows = 0;

        const int8_t *filter_data_ptr = &filter_data[0];
        const int32_t *bias_data_ptr = &bias_data[0];
        const int32_t *output_mult_ptr = &output_mult[0];
        const int32_t *output_shift_ptr = &output_shift[0];

        for (int32_t i_group = 0; i_group < groups; i_group++)
        {
            int8_t *out = output_data + i_group * output_ch_per_group;
            for (int i_out_y = 0; i_out_y < output_y; i_out_y++)
            {
                for (int i_out_x = 0; i_out_x < output_x; i_out_x++)
                {
                    const int32_t base_idx_x = stride_x * i_out_x - pad_x;
                    const int32_t base_idx_y = stride_y * i_out_y - pad_y;

                    if (y_rshift == 1 || x_rshift == 1)
                    {

                        arm_memset_s8(
                            im2col_buf, (int8_t)-input_offset, sizeof(int8_t) * kernel_ch * kernel_x * kernel_y);
                        for (int32_t i_ker_y = 0; i_ker_y < kernel_y; i_ker_y++)
                        {
                            const int32_t k_y = base_idx_y + dilation_y * i_ker_y;

                            if ((k_y < 0 || k_y >= input_y) || (k_y % 2 && y_rshift == 1))
                            {
                                im2col_buf += kernel_ch * kernel_x;
                            }
                            else
                            {
                                const int32_t k_y_rshifted = k_y >> y_rshift;
                                for (int32_t i_ker_x = 0; i_ker_x < kernel_x; i_ker_x++)
                                {
                                    const int32_t k_x = base_idx_x + dilation_x * i_ker_x;

                                    if ((k_x >= 0 && k_x < input_x) && ((k_x % 2 == 0) || x_rshift == 0))
                                    {
                                        const int32_t k_x_rshifted = k_x >> x_rshift;
                                        arm_memcpy_s8(im2col_buf,
                                                      input_data +
                                                          (k_y_rshifted * input_x_rshifted + k_x_rshifted) * input_ch,
                                                      sizeof(int8_t) * kernel_ch);
                                    }
                                    im2col_buf += kernel_ch;
                                }
                            }
                        }
                    }
                    else
                    {
                        for (int32_t i_ker_y = 0; i_ker_y < kernel_y; i_ker_y++)
                        {
                            for (int32_t i_ker_x = 0; i_ker_x < kernel_x; i_ker_x++)
                            {
                                const int32_t k_y = base_idx_y + dilation_y * i_ker_y;
                                const int32_t k_x = base_idx_x + dilation_x * i_ker_x;

                                if (k_y < 0 || k_y >= input_y || k_x < 0 || k_x >= input_x)
                                {
                                    arm_memset_s8(im2col_buf, (int8_t)-input_offset, sizeof(int8_t) * kernel_ch);
                                }
                                else
                                {
                                    arm_memcpy_s8(im2col_buf,
                                                  input_data + (k_y * input_x + k_x) * input_ch + i_group * kernel_ch,
                                                  sizeof(int8_t) * kernel_ch);
                                }
                                im2col_buf += kernel_ch;
                            }
                        }
                    }
                    lhs_rows++;

                    arm_q7_to_q15_with_offset(
                        im2col_buf - rhs_cols, im2col_buf_start_s16, rhs_cols, (int16_t)input_offset);

                    im2col_buf_start_s16 += aligned_rhs_cols;

                    if (lhs_rows == 2)
                    {
                        if (groups > 1)
                        {
                            out = arm_nn_mat_mult_kernel_row_offset_s8_s16(filter_data_ptr,
                                                                           buffer_a,
                                                                           output_ch_per_group,
                                                                           output_shift_ptr,
                                                                           output_mult_ptr,
                                                                           out_offset,
                                                                           out_activation_min,
                                                                           out_activation_max,
                                                                           rhs_cols,
                                                                           aligned_rhs_cols,
                                                                           bias_data_ptr,
                                                                           output_ch,
                                                                           out);
                        }
                        else
                        {
                            out = arm_nn_mat_mult_kernel_s8_s16(filter_data_ptr,
                                                                buffer_a,
                                                                output_ch_per_group,
                                                                output_shift_ptr,
                                                                output_mult_ptr,
                                                                out_offset,
                                                                out_activation_min,
                                                                out_activation_max,
                                                                rhs_cols,
                                                                aligned_rhs_cols,
                                                                bias_data_ptr,
                                                                out);
                        }

                        im2col_buf_start_s16 = buffer_a;
                        im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
                        lhs_rows = 0;
                    }

                }
            }

            if (out == NULL)
            {
                return ARM_CMSIS_NN_NO_IMPL_ERROR;
            }

            if (lhs_rows != 0)
            {

                const int8_t *ker_a = filter_data_ptr;
                int i;

                for (i = 0; i < output_ch_per_group; i++)
                {

                    int32_t sum = 0;
                    if (bias_data_ptr)
                    {
                        sum = bias_data_ptr[i];
                    }

                    const int16_t *ip_as_col = buffer_a;

                    uint16_t col_count = rhs_cols;

                    while (col_count)
                    {
                        int8_t ker_a1 = *ker_a++;
                        int16_t ip_b1 = *ip_as_col++;

                        sum += ker_a1 * ip_b1;
                        col_count--;
                    }

                    sum = arm_nn_requantize(sum, output_mult_ptr[i], output_shift_ptr[i]);
                    sum += out_offset;
                    sum = MAX(sum, out_activation_min);
                    sum = MIN(sum, out_activation_max);
                    *out++ = (int8_t)sum;
                }

                im2col_buf_start_s16 = buffer_a;
                im2col_buf = (int8_t *)buffer_a + aligned_rhs_cols * 2;
                lhs_rows = 0;

            }
            filter_data_ptr += output_ch_per_group * rhs_cols;
            bias_data_ptr += output_ch_per_group;
            output_mult_ptr += output_ch_per_group;
            output_shift_ptr += output_ch_per_group;
        }

        input_data += (input_x_rshifted * input_y_rshifted * input_ch);
        output_data += (output_x * output_y * output_ch);
    }

    return ARM_CMSIS_NN_SUCCESS;
}

arm_cmsis_nn_status arm_convolve_s8(const cmsis_nn_context *ctx,
                                    const cmsis_nn_conv_params *conv_params,
                                    const cmsis_nn_per_channel_quant_params *quant_params,
                                    const cmsis_nn_dims *input_dims,
                                    const int8_t *input_data,
                                    const cmsis_nn_dims *filter_dims,
                                    const int8_t *filter_data,
                                    const cmsis_nn_dims *bias_dims,
                                    const int32_t *bias_data,
                                    const cmsis_nn_dims *upscale_dims,
                                    const cmsis_nn_dims *output_dims,
                                    int8_t *output_data)
{
    if (ctx->buf == NULL)
        return ARM_CMSIS_NN_ARG_ERROR;
    if (upscale_dims && (upscale_dims->h == 2 || upscale_dims->w == 2))
        return arm_convolve_s8_ref(ctx, conv_params, quant_params, input_dims, input_data, filter_dims, filter_data,
                                   bias_dims, bias_data, upscale_dims, output_dims, output_data);
    if (input_dims->c % filter_dims->c != 0 || output_dims->c % (input_dims->c / filter_dims->c) != 0)
        return ARM_CMSIS_NN_ARG_ERROR;
    (void)bias_dims;
    ime_conv_s8(conv_params, quant_params, input_dims, input_data, filter_dims, filter_data, bias_data, output_dims,
                output_data);
    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_convolve_1_x_n_s8(const cmsis_nn_context *ctx,
                                          const cmsis_nn_conv_params *conv_params,
                                          const cmsis_nn_per_channel_quant_params *quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *filter_dims,
                                          const int8_t *filter_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    arm_cmsis_nn_status status = ARM_CMSIS_NN_SUCCESS;

    if ((input_dims->h != 1) || conv_params->dilation.w != 1 || ctx->buf == NULL || conv_params->stride.w == 0 ||
        (conv_params->stride.w * input_dims->c % 4 != 0))
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }

    (void)bias_dims;
    ime_conv_s8(conv_params, quant_params, input_dims, input_data, filter_dims, filter_data, bias_data, output_dims,
                output_data);
    return status;
    status = arm_convolve_s8(ctx,
                             conv_params,
                             quant_params,
                             input_dims,
                             input_data,
                             filter_dims,
                             filter_data,
                             bias_dims,
                             bias_data,
                             NULL,
                             output_dims,
                             output_data);

    return status;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


static arm_cmsis_nn_status arm_transpose_conv_s8_ref(const cmsis_nn_context *ctx,
                                          const cmsis_nn_context *output_ctx,
                                          const cmsis_nn_transpose_conv_params *transpose_conv_params,
                                          const cmsis_nn_per_channel_quant_params *quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *filter_dims,
                                          const int8_t *filter_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    (void)bias_dims;
    (void)output_ctx;

    const int32_t activation_min = transpose_conv_params->activation.min;
    const int32_t activation_max = transpose_conv_params->activation.max;

    const int32_t input_ch = input_dims->c;
    const int32_t input_x = input_dims->w;
    const int32_t input_y = input_dims->h;

    const int32_t output_x = output_dims->w;
    const int32_t output_y = output_dims->h;

    const int32_t output_ch = output_dims->c;

    const int32_t filter_x = filter_dims->w;
    const int32_t filter_y = filter_dims->h;

    const int32_t pad_x = transpose_conv_params->padding.w;
    const int32_t pad_y = transpose_conv_params->padding.h;

    const int32_t stride_x = transpose_conv_params->stride.w;
    const int32_t stride_y = transpose_conv_params->stride.h;

    const int32_t *output_multiplier = quant_params->multiplier;
    const int32_t *output_shift = quant_params->shift;

    const int32_t out_offset = transpose_conv_params->output_offset;
    const int32_t input_offset = transpose_conv_params->input_offset;

    const int32_t buf_x_elements = ((input_x - 1) * stride_x + MAX(filter_x, stride_x));
    const int32_t buf_x = buf_x_elements * output_ch;
    const int32_t buf_y = MAX(filter_y, stride_y);
    const int32_t buf_size = buf_y * buf_x;
    int32_t *buf = ctx->buf;
    int32_t batch_cnt = input_dims->n;

    const int8_t *filter = filter_data;
    const int8_t *input = input_data;
    int8_t *output = output_data;

    while (batch_cnt)
    {

        if (bias_data)
        {
            for (int x = 0; x < buf_x_elements * buf_y; x++)
            {
                arm_memcpy_s8((int8_t *)(buf + x * output_ch), (const int8_t *)bias_data, output_ch * sizeof(int32_t));
            }
        }
        else
        {
            arm_memset_s8((int8_t *)buf, 0, buf_size * sizeof(int32_t));
        }

        int32_t buf_row = 0;
        for (int j = 0; j < input_y; j++)
        {
            int skip_rows_top = MAX(0, pad_y - j * stride_y);
            int skip_rows_bottom = MAX(0, (j * stride_y + filter_y) - (pad_y + output_y) - 1);

            arm_nn_transpose_conv_row_s8_s32(input,
                                             filter,
                                             buf,
                                             buf_row,
                                             buf_size,
                                             filter_y,
                                             filter_x,
                                             input_ch,
                                             output_ch,
                                             input_offset,
                                             buf_x,
                                             input_x,
                                             stride_x,
                                             skip_rows_top,
                                             skip_rows_bottom);
            input += input_ch * input_x;

            const int32_t rows_to_flush = MAX(0, (j + 1) * stride_y - pad_y) - MAX(0, j * stride_y - pad_y);

            if (rows_to_flush > 0)
            {
                for (int y = 0; y < rows_to_flush; y++)
                {
                    int32_t *buf_out = buf + buf_row;
                    buf_out += output_ch * pad_x;

                    for (int x = 0; x < output_x; x++)
                    {
                        const int32_t *output_multiplier_ptr = output_multiplier;
                        const int32_t *output_shift_ptr = output_shift;
                        for (int z = 0; z < output_ch; z++)
                        {
                            int32_t result = *buf_out++;
                            result = arm_nn_requantize(result, *output_multiplier_ptr++, *output_shift_ptr++);
                            result += out_offset;
                            result = MAX(result, activation_min);
                            result = MIN(result, activation_max);
                            *output++ = result;
                        }
                    }

                    if (bias_data)
                    {
                        for (int x = 0; x < buf_x_elements; x++)
                        {
                            arm_memcpy_s8((int8_t *)(buf + buf_row + x * output_ch),
                                          (const int8_t *)bias_data,
                                          output_ch * sizeof(int32_t));
                        }
                    }
                    else
                    {
                        arm_memset_s8((int8_t *)(buf + buf_row), 0, buf_x * sizeof(int32_t));
                    }

                    buf_row = (buf_row + buf_x) % buf_size;
                }
            }
        }

        for (int y = 0; y < filter_y - stride_y; y++)
        {
            int32_t *buf_out = buf + buf_row;
            if ((input_y * stride_y + y >= pad_y) && (input_y * stride_y + y < pad_y + output_y))
            {
                buf_out += output_ch * pad_x;

                for (int x = 0; x < output_x; x++)
                {
                    const int32_t *output_multiplier_ptr = output_multiplier;
                    const int32_t *output_shift_ptr = output_shift;

                    for (int z = 0; z < output_ch; z++)
                    {
                        int32_t result = *buf_out++;

                        result = arm_nn_requantize(result, *output_multiplier_ptr++, *output_shift_ptr++);
                        result += out_offset;
                        result = MAX(result, activation_min);
                        result = MIN(result, activation_max);
                        *output++ = result;
                    }
                }

            }
            buf_row = (buf_row + buf_x) % buf_size;
        }

        batch_cnt--;
    }

    return ARM_CMSIS_NN_SUCCESS;
}

arm_cmsis_nn_status arm_transpose_conv_s8(const cmsis_nn_context *ctx,
                                          const cmsis_nn_context *output_ctx,
                                          const cmsis_nn_transpose_conv_params *tp,
                                          const cmsis_nn_per_channel_quant_params *quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *filter_dims,
                                          const int8_t *filter_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    (void)ctx;
    (void)output_ctx;
    (void)bias_dims;
    const int32_t in_ch = input_dims->c, in_x = input_dims->w, in_y = input_dims->h;
    const int32_t out_x = output_dims->w, out_y = output_dims->h, out_ch = output_dims->c;
    const int32_t f_x = filter_dims->w, f_y = filter_dims->h;
    const int32_t taps = out_ch * f_y * f_x, pixels = in_x * in_y;
    int32_t *col = (int32_t *)malloc((size_t)pixels * taps * sizeof(int32_t));
    int32_t *img = (int32_t *)malloc((size_t)out_x * out_y * out_ch * sizeof(int32_t));
    int32_t *zero = (int32_t *)calloc(out_ch, sizeof(int32_t));
    for (int b = 0; b < input_dims->n; b++)
    {
        const int8_t *in = input_data + (long)b * pixels * in_ch;
        int8_t *out = output_data + (long)b * out_x * out_y * out_ch;
        /* col[p][(co, ky, kx)] = sum_ci (in[p][ci] + input_offset) * filter[co][ky][kx][ci] */
        ime_gemm_s8(in, in_ch, pixels, filter_data, taps, in_ch, col);
        for (int p = 0; p < pixels; p++)
            for (int t = 0; t < taps; t++)
                col[(long)p * taps + t] += tp->input_offset * ime_bsum[t];
        for (long i = 0; i < (long)out_x * out_y; i++)
            memcpy(img + i * out_ch, bias_data ? bias_data : zero, out_ch * sizeof(int32_t));
        for (int iy = 0; iy < in_y; iy++)
            for (int ix = 0; ix < in_x; ix++)
            {
                const int32_t *c = col + ((long)iy * in_x + ix) * taps;
                for (int ky = 0; ky < f_y; ky++)
                {
                    const int32_t oy = iy * tp->stride.h + ky - tp->padding.h;
                    if (oy < 0 || oy >= out_y)
                        continue;
                    for (int kx = 0; kx < f_x; kx++)
                    {
                        const int32_t ox = ix * tp->stride.w + kx - tp->padding.w;
                        if (ox < 0 || ox >= out_x)
                            continue;
                        int32_t *o = img + ((long)oy * out_x + ox) * out_ch;
                        const int32_t *s = c + ky * f_x + kx;
                        for (int co = 0; co < out_ch; co++)
                            o[co] += s[(long)co * f_y * f_x];
                    }
                }
            }
        for (long i = 0; i < (long)out_x * out_y; i++)
            ime_requant_row(img + i * out_ch, zero, 0, quant_params->multiplier, quant_params->shift, 1,
                            tp->output_offset, tp->activation.min, tp->activation.max, out_ch, out + i * out_ch);
    }
    free(col);
    free(img);
    free(zero);
    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


static arm_cmsis_nn_status arm_transpose_conv_s8_ref(const cmsis_nn_context *ctx,
                                          const cmsis_nn_context *output_ctx,
                                          const cmsis_nn_transpose_conv_params *transpose_conv_params,
                                          const cmsis_nn_per_channel_quant_params *quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *filter_dims,
                                          const int8_t *filter_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    (void)bias_dims;
    (void)output_ctx;

    const int32_t activation_min = transpose_conv_params->activation.min;
    const int32_t activation_max = transpose_conv_params->activation.max;

    const int32_t input_ch = input_dims->c;
    const int32_t input_x = input_dims->w;
    const int32_t input_y = input_dims->h;

    const int32_t output_x = output_dims->w;
    const int32_t output_y = output_dims->h;

    const int32_t output_ch = output_dims->c;

    const int32_t filter_x = filter_dims->w;
    const int32_t filter_y = filter_dims->h;

    const int32_t pad_x = transpose_conv_params->padding.w;
    const int32_t pad_y = transpose_conv_params->padding.h;

    const int32_t stride_x = transpose_conv_params->stride.w;
    const int32_t stride_y = transpose_conv_params->stride.h;

    const int32_t *output_multiplier = quant_params->multiplier;
    const int32_t *output_shift = quant_params->shift;

    const int32_t out_offset = transpose_conv_params->output_offset;
    const int32_t input_offset = transpose_conv_params->input_offset;

    const int32_t buf_x_elements = ((input_x - 1) * stride_x + MAX(filter_x, stride_x));
    const int32_t buf_x = buf_x_elements * output_ch;
    const int32_t buf_y = MAX(filter_y, stride_y);
    const int32_t buf_size = buf_y * buf_x;
    int32_t *buf = ctx->buf;
    int32_t batch_cnt = input_dims->n;

    const int8_t *filter = filter_data;
    const int8_t *input = input_data;
    int8_t *output = output_data;

    while (batch_cnt)
    {

        if (bias_data)
        {
            for (int x = 0; x < buf_x_elements * buf_y; x++)
            {
                arm_memcpy_s8((int8_t *)(buf + x * output_ch), (const int8_t *)bias_data, output_ch * sizeof(int32_t));
            }
        }
        else
        {
            arm_memset_s8((int8_t *)buf, 0, buf_size * sizeof(int32_t));
        }

        int32_t buf_row = 0;
        for (int j = 0; j < input_y; j++)
        {
            int skip_rows_top = MAX(0, pad_y - j * stride_y);
            int skip_rows_bottom = MAX(0, (j * stride_y + filter_y) - (pad_y + output_y) - 1);

            arm_nn_transpose_conv_row_s8_s32(input,
                                             filter,
                                             buf,
                                             buf_row,
                                             buf_size,
                                             filter_y,
                                             filter_x,
                                             input_ch,
                                             output_ch,
                                             input_offset,
                                             buf_x,
                                             input_x,
                                             stride_x,
                                             skip_rows_top,
                                             skip_rows_bottom);
            input += input_ch * input_x;

            const int32_t rows_to_flush = MAX(0, (j + 1) * stride_y - pad_y) - MAX(0, j * stride_y - pad_y);

            if (rows_to_flush > 0)
            {
                for (int y = 0; y < rows_to_flush; y++)
                {
                    int32_t *buf_out = buf + buf_row;
                    buf_out += output_ch * pad_x;

                    for (int x = 0; x < output_x; x++)
                    {
                        const int32_t *output_multiplier_ptr = output_multiplier;
                        const int32_t *output_shift_ptr = output_shift;
                        for (int z = 0; z < output_ch; z++)
                        {
                            int32_t result = *buf_out++;
                            result = arm_nn_requantize(result, *output_multiplier_ptr++, *output_shift_ptr++);
                            result += out_offset;
                            result = MAX(result, activation_min);
                            result = MIN(result, activation_max);
                            *output++ = result;
                        }
                    }

                    if (bias_data)
                    {
                        for (int x = 0; x < buf_x_elements; x++)
                        {
                            arm_memcpy_s8((int8_t *)(buf + buf_row + x * output_ch),
                                          (const int8_t *)bias_data,
                                          output_ch * sizeof(int32_t));
                        }
                    }
                    else
                    {
                        arm_memset_s8((int8_t *)(buf + buf_row), 0, buf_x * sizeof(int32_t));
                    }

                    buf_row = (buf_row + buf_x) % buf_size;
                }
            }
        }

        for (int y = 0; y < filter_y - stride_y; y++)
        {
            int32_t *buf_out = buf + buf_row;
            if ((input_y * stride_y + y >= pad_y) && (input_y * stride_y + y < pad_y + output_y))
            {
                buf_out += output_ch * pad_x;

                for (int x = 0; x < output_x; x++)
                {
                    const int32_t *output_multiplier_ptr = output_multiplier;
                    const int32_t *output_shift_ptr = output_shift;

                    for (int z = 0; z < output_ch; z++)
                    {
                        int32_t result = *buf_out++;

                        result = arm_nn_requantize(result, *output_multiplier_ptr++, *output_shift_ptr++);
                        result += out_offset;
                        result = MAX(result, activation_min);
                        result = MIN(result, activation_max);
                        *output++ = result;
                    }
                }

            }
            buf_row = (buf_row + buf_x) % buf_size;
        }

        batch_cnt--;
    }

    return ARM_CMSIS_NN_SUCCESS;
}

arm_cmsis_nn_status arm_transpose_conv_s8(const cmsis_nn_context *ctx,
                                          const cmsis_nn_context *output_ctx,
                                          const cmsis_nn_transpose_conv_params *tp,
                                          const cmsis_nn_per_channel_quant_params *quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *filter_dims,
                                          const int8_t *filter_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    (void)ctx;
    (void)output_ctx;
    (void)bias_dims;
    const int32_t in_ch = input_dims->c, in_x = input_dims->w, in_y = input_dims->h;
    const int32_t out_x = output_dims->w, out_y = output_dims->h, out_ch = output_dims->c;
    const int32_t f_x = filter_dims->w, f_y = filter_dims->h;
    const int32_t taps = out_ch * f_y * f_x, pixels = in_x * in_y;
    int32_t *col = (int32_t *)malloc((size_t)pixels * taps * sizeof(int32_t));
    int32_t *img = (int32_t *)malloc((size_t)out_x * out_y * out_ch * sizeof(int32_t));
    int32_t *zero = (int32_t *)calloc(out_ch, sizeof(int32_t));
    for (int b = 0; b < input_dims->n; b++)
    {
        const int8_t *in = input_data + (long)b * pixels * in_ch;
        int8_t *out = output_data + (long)b * out_x * out_y * out_ch;
        /* col[p][(co, ky, kx)] = sum_ci (in[p][ci] + input_offset) * filter[co][ky][kx][ci] */
        ime_gemm_s8(in, in_ch, pixels, filter_data, taps, in_ch, col);
        for (int p = 0; p < pixels; p++)
            for (int t = 0; t < taps; t++)
                col[(long)p * taps + t] += tp->input_offset * ime_bsum[t];
        for (long i = 0; i < (long)out_x * out_y; i++)
            memcpy(img + i * out_ch, bias_data ? bias_data : zero, out_ch * sizeof(int32_t));
        for (int iy = 0; iy < in_y; iy++)
            for (int ix = 0; ix < in_x; ix++)
            {
                const int32_t *c = col + ((long)iy * in_x + ix) * taps;
                for (int ky = 0; ky < f_y; ky++)
                {
                    const int32_t oy = iy * tp->stride.h + ky - tp->padding.h;
                    if (oy < 0 || oy >= out_y)
                        continue;
                    for (int kx = 0; kx < f_x; kx++)
                    {
                        const int32_t ox = ix * tp->stride.w + kx - tp->padding.w;
                        if (ox < 0 || ox >= out_x)
                            continue;
                        int32_t *o = img + ((long)oy * out_x + ox) * out_ch;
                        const int32_t *s = c + ky * f_x + kx;
                        for (int co = 0; co < out_ch; co++)
                            o[co] += s[(long)co * f_y * f_x];
                    }
                }
            }
        for (long i = 0; i < (long)out_x * out_y; i++)
            ime_requant_row(img + i * out_ch, zero, 0, quant_params->multiplier, quant_params->shift, 1,
                            tp->output_offset, tp->activation.min, tp->activation.max, out_ch, out + i * out_ch);
    }
    free(col);
    free(img);
    free(zero);
    return ARM_CMSIS_NN_SUCCESS;
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_svdf_s8(const cmsis_nn_context *ctx,
                                const cmsis_nn_context *input_ctx,
                                const cmsis_nn_context *output_ctx,
                                const cmsis_nn_svdf_params *svdf_params,
                                const cmsis_nn_per_tensor_quant_params *input_quant_params,
                                const cmsis_nn_per_tensor_quant_params *output_quant_params,
                                const cmsis_nn_dims *input_dims,
                                const int8_t *input_data,
                                const cmsis_nn_dims *state_dims,
                                int8_t *state_data,
                                const cmsis_nn_dims *weights_feature_dims,
                                const int8_t *weights_feature_data,
                                const cmsis_nn_dims *weights_time_dims,
                                const int8_t *weights_time_data,
                                const cmsis_nn_dims *bias_dims,
                                const int32_t *bias_data,
                                const cmsis_nn_dims *output_dims,
                                int8_t *output_data)
{
    (void)bias_dims;
    (void)state_dims;
    (void)output_dims;

    const int32_t multiplier_in = input_quant_params->multiplier;
    const int32_t shift_in = input_quant_params->shift;
    const int32_t multiplier_out = output_quant_params->multiplier;
    const int32_t shift_2 = output_quant_params->shift;
    const int32_t zp_in = svdf_params->input_offset;
    const int32_t zp_out = svdf_params->output_offset;
    const int32_t in_activation_min = svdf_params->input_activation.min;
    const int32_t in_activation_max = svdf_params->input_activation.max;
    const int32_t out_activation_min = svdf_params->output_activation.min;
    const int32_t out_activation_max = svdf_params->output_activation.max;
    const int16_t rank = svdf_params->rank;

    const int32_t input_batches = input_dims->n;
    const int32_t input_height = input_dims->h;
    const int32_t feature_batches = weights_feature_dims->n;
    const int32_t time_batches = weights_time_dims->h;
    const int32_t unit_count = feature_batches / rank;

    if (input_ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int32_t *buffer_a = (int32_t *)input_ctx->buf;

    if (output_ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int32_t *buffer_b = (int32_t *)output_ctx->buf;


    memmove(state_data,
            state_data + 1,
            (size_t)((input_batches * feature_batches * time_batches - 1) * (int32_t)sizeof(int8_t)));

    {
        int32_t *acc = (int32_t *)malloc((size_t)input_batches * feature_batches * sizeof(int32_t));
        ime_gemm_s8(input_data, input_height, input_batches, weights_feature_data, feature_batches, input_height, acc);
        const int32_t *bsum = ime_bsum;
        for (int b = 0; b < input_batches; b++)
        {
            int8_t *res_ptr = state_data + (time_batches * b * feature_batches) + (time_batches - 1);
            const int32_t *a = acc + (long)b * feature_batches;
            for (int f = 0; f < feature_batches; f++)
            {
                int32_t v = arm_nn_requantize(a[f] - zp_in * bsum[f], multiplier_in, shift_in);
                v = MAX(v, in_activation_min);
                v = MIN(v, in_activation_max);
                res_ptr[(long)f * time_batches] = (int8_t)v;
            }
        }
        free(acc);
    }

    {
        int32_t *ptr_a = buffer_a;
        const int8_t *v2 = state_data;
        for (int i_batch = 0; i_batch < input_batches; i_batch++)
        {
            const int8_t *v1 = weights_time_data;

            for (int i_feature_batch = 0; i_feature_batch < feature_batches; i_feature_batch++)
            {
                *ptr_a = 0;
                int32_t sum = 0;

                for (int j = 0; j < time_batches; j++)
                {
                    sum += *v1 * *v2;
                    v1++;
                    v2++;
                }

                *ptr_a = sum;
                ptr_a++;
            }
        }
    }

    if (bias_data)
    {
        if (unit_count == feature_batches)
        {
            for (int i = 0; i < input_batches; i++)
            {
                int32_t *output_temp = buffer_b + i * feature_batches;
                const int32_t *ptr_a = buffer_a + i * feature_batches;

                const int32_t *bi = bias_data;
                for (int j = 0; j < feature_batches; j++)
                {
                    output_temp[j] = ptr_a[j] + bi[j];
                }
            }
        }
        else
        {
            for (int i_batch = 0; i_batch < input_batches; i_batch++)
            {
                int32_t *output_data_temp = buffer_b + i_batch * unit_count;
                int32_t *ptr_a = buffer_a + i_batch * feature_batches;

                for (int i = 0; i < unit_count; i++)
                {
                    int32_t sum = bias_data[i];
                    for (int j = 0; j < rank; j++)
                    {
                        sum += *ptr_a;
                        ptr_a++;
                    }
                    output_data_temp[i] = sum;
                }
            }
        }
    }
    else
    {
        for (int i_batch = 0; i_batch < input_batches; i_batch++)
        {
            int32_t *output_data_temp = buffer_b + i_batch * unit_count;
            int32_t *ptr_a = buffer_a + i_batch * feature_batches;

            for (int i = 0; i < unit_count; i++)
            {
                int32_t sum = 0;
                for (int j = 0; j < rank; j++)
                {
                    sum += *ptr_a;
                    ptr_a++;
                }
                output_data_temp[i] = sum;
            }
        }
    }

    for (int i = 0; i < input_batches * unit_count; i++)
    {
        output_data[i] = (int8_t)CLAMP(
            arm_nn_requantize(buffer_b[i], multiplier_out, shift_2) + zp_out, out_activation_max, out_activation_min);
    }

    return (ARM_CMSIS_NN_SUCCESS);
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


arm_cmsis_nn_status arm_svdf_state_s16_s8(const cmsis_nn_context *input_ctx,
                                          const cmsis_nn_context *output_ctx,
                                          const cmsis_nn_svdf_params *svdf_params,
                                          const cmsis_nn_per_tensor_quant_params *input_quant_params,
                                          const cmsis_nn_per_tensor_quant_params *output_quant_params,
                                          const cmsis_nn_dims *input_dims,
                                          const int8_t *input_data,
                                          const cmsis_nn_dims *state_dims,
                                          int16_t *state_data,
                                          const cmsis_nn_dims *weights_feature_dims,
                                          const int8_t *weights_feature_data,
                                          const cmsis_nn_dims *weights_time_dims,
                                          const int16_t *weights_time_data,
                                          const cmsis_nn_dims *bias_dims,
                                          const int32_t *bias_data,
                                          const cmsis_nn_dims *output_dims,
                                          int8_t *output_data)
{
    (void)bias_dims;
    (void)state_dims;
    (void)output_dims;

    const int32_t multiplier_in = input_quant_params->multiplier;
    const int32_t shift_in = input_quant_params->shift;
    const int32_t multiplier_out = output_quant_params->multiplier;
    const int32_t shift_2 = output_quant_params->shift;
    const int32_t zp_in = svdf_params->input_offset;
    const int32_t zp_out = svdf_params->output_offset;
    const int32_t in_activation_min = svdf_params->input_activation.min;
    const int32_t in_activation_max = svdf_params->input_activation.max;
    const int32_t out_activation_min = svdf_params->output_activation.min;
    const int32_t out_activation_max = svdf_params->output_activation.max;
    const int16_t rank = svdf_params->rank;

    const int32_t input_batches = input_dims->n;
    const int32_t input_height = input_dims->h;
    const int32_t feature_batches = weights_feature_dims->n;
    const int32_t time_batches = weights_time_dims->h;
    const int32_t unit_count = feature_batches / rank;

    if (input_ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int32_t *buffer_a = (int32_t *)input_ctx->buf;

    if (output_ctx->buf == NULL)
    {
        return ARM_CMSIS_NN_ARG_ERROR;
    }
    int32_t *buffer_b = (int32_t *)output_ctx->buf;

    memmove(state_data,
            state_data + 1,
            (size_t)((input_batches * feature_batches * time_batches - 1) * (int32_t)sizeof(int16_t)));

    {
        int32_t *acc = (int32_t *)malloc((size_t)input_batches * feature_batches * sizeof(int32_t));
        ime_gemm_s8(input_data, input_height, input_batches, weights_feature_data, feature_batches, input_height, acc);
        const int32_t *bsum = ime_bsum;
        for (int b = 0; b < input_batches; b++)
        {
            int16_t *res_ptr = state_data + (time_batches * b * feature_batches) + (time_batches - 1);
            const int32_t *a = acc + (long)b * feature_batches;
            for (int f = 0; f < feature_batches; f++)
            {
                int32_t v = arm_nn_requantize(a[f] - zp_in * bsum[f], multiplier_in, shift_in);
                v = MAX(v, in_activation_min);
                v = MIN(v, in_activation_max);
                res_ptr[(long)f * time_batches] = (int16_t)v;
            }
        }
        free(acc);
    }

    {

        int32_t *ptr_a = buffer_a;
        const int16_t *v2 = state_data;
        for (int i_batch = 0; i_batch < input_batches; i_batch++)
        {
            const int16_t *v1 = weights_time_data;

            for (int i_feature_batch = 0; i_feature_batch < feature_batches; i_feature_batch++)
            {
                *ptr_a = 0;
                int32_t sum = 0;

                for (int j = 0; j < time_batches; j++)
                {
                    sum += *v1 * *v2;
                    v1++;
                    v2++;
                }

                *ptr_a = sum;
                ptr_a++;
            }
        }
    }

    if (bias_data)
    {
        if (unit_count == feature_batches)
        {
            for (int i = 0; i < input_batches; i++)
            {
                int32_t *output_temp = buffer_b + i * feature_batches;
                const int32_t *ptr_a = buffer_a + i * feature_batches;

                const int32_t *bi = bias_data;
                for (int j = 0; j < feature_batches; j++)
                {
                    output_temp[j] = ptr_a[j] + bi[j];
                }
            }
        }
        else
        {
            for (int i_batch = 0; i_batch < input_batches; i_batch++)
            {
                int32_t *output_data_temp = buffer_b + i_batch * unit_count;
                int32_t *ptr_a = buffer_a + i_batch * feature_batches;

                for (int i = 0; i < unit_count; i++)
                {
                    int32_t sum = bias_data[i];
                    for (int j = 0; j < rank; j++)
                    {
                        sum += *ptr_a;
                        ptr_a++;
                    }
                    output_data_temp[i] = sum;
                }
            }
        }
    }
    else
    {
        for (int i_batch = 0; i_batch < input_batches; i_batch++)
        {
            int32_t *output_data_temp = buffer_b + i_batch * unit_count;
            int32_t *ptr_a = buffer_a + i_batch * feature_batches;

            for (int i = 0; i < unit_count; i++)
            {
                int32_t sum = 0;
                for (int j = 0; j < rank; j++)
                {
                    sum += *ptr_a;
                    ptr_a++;
                }
                output_data_temp[i] = sum;
            }
        }
    }

    for (int i = 0; i < input_batches * unit_count; i++)
    {
        output_data[i] = (int8_t)CLAMP(
            arm_nn_requantize(buffer_b[i], multiplier_out, shift_2) + zp_out, out_activation_max, out_activation_min);
    }

    return (ARM_CMSIS_NN_SUCCESS);
}

#include "cmsisnn.h"

/* ---- SpacemiT IME (X60, VLEN 256) int8 GEMM core ----
   C[m][n] = sum_k A[m*lda + k] * B[n*K + k]  (raw int32 dot products).
   A and B are packed into zero-padded 4x8 tiles. vmadot (signed x signed)
   accumulates a 4x4 int32 tile C += A_tile * B_tile^T; each pass computes
   two neighbouring C tiles (v16/v17 and v18/v19) so every A tile is loaded
   once for both. The requantization epilogue is vectorized with RVV. */
#include <stdlib.h>
#include <string.h>
#include <riscv_vector.h>
#define IME_MIN_WORK 8192

static void ime_pack4x8(const int8_t *src, int ld, int rows, int k, int kb, int tiles, int8_t *dst)
{
    memset(dst, 0, (size_t)tiles * kb * 32);
    for (int r = 0; r < rows; r++)
    {
        const int8_t *s = src + (long)r * ld;
        int8_t *d = dst + (long)(r / 4) * kb * 32 + (r % 4) * 8;
        int kk = 0;
        for (; kk + 8 <= k; kk += 8)
            memcpy(d + (kk / 8) * 32, s + kk, 8);
        for (; kk < k; kk++)
            d[(kk / 8) * 32 + (kk % 8)] = s[kk];
    }
}

/* Weights are constant during inference: keep the last few packed B
   matrices (one per group/layer) and their row sums. */
#define IME_CACHE 8
static struct { const int8_t *key; int n, k; int8_t *pb; int32_t *bsum; } ime_cache[IME_CACHE];
static int ime_cache_next;
static int32_t *ime_bsum;
static int8_t *ime_pa;
static size_t ime_pa_cap;
static int32_t *ime_acc;
static size_t ime_acc_cap;

static const int8_t *ime_packed_b(const int8_t *B, int N, int K)
{
    for (int e = 0; e < IME_CACHE; e++)
        if (ime_cache[e].key == B && ime_cache[e].n == N && ime_cache[e].k == K)
        {
            ime_bsum = ime_cache[e].bsum;
            return ime_cache[e].pb;
        }
    int e = ime_cache_next;
    ime_cache_next = (e + 1) % IME_CACHE;
    int kb = (K + 7) / 8, nb2 = ((N + 7) / 8) * 2;
    free(ime_cache[e].pb);
    free(ime_cache[e].bsum);
    ime_cache[e].pb = (int8_t *)malloc((size_t)nb2 * kb * 32);
    ime_cache[e].bsum = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    ime_pack4x8(B, K, N, K, kb, nb2, ime_cache[e].pb);
    for (int n = 0; n < N; n++)
    {
        int32_t s = 0;
        for (int k = 0; k < K; k++)
            s += B[(long)n * K + k];
        ime_cache[e].bsum[n] = s;
    }
    ime_cache[e].key = B, ime_cache[e].n = N, ime_cache[e].k = K;
    ime_bsum = ime_cache[e].bsum;
    return ime_cache[e].pb;
}

static void ime_gemm_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K, int32_t *C)
{
    int kb = (K + 7) / 8, mb = (M + 3) / 4, nb2 = ((N + 7) / 8) * 2;
    const int8_t *pb = ime_packed_b(B, N, K);
    if ((size_t)mb * kb * 32 > ime_pa_cap)
    {
        free(ime_pa);
        ime_pa_cap = (size_t)mb * kb * 32;
        ime_pa = (int8_t *)malloc(ime_pa_cap);
    }
    int8_t *pa = ime_pa;
    ime_pack4x8(A, lda, M, K, kb, mb, pa);
    int32_t tile[32];
    /* B-tile pairs outer: the packed weights stream through the cache once
       while the (smaller) packed A stays resident. */
    for (int j = 0; j < nb2; j += 2)
        for (int i = 0; i < mb; i++)
        {
            const int8_t *a = pa + (long)i * kb * 32, *b = pb + (long)j * kb * 32;
            const int8_t *b2 = b + (long)kb * 32;
            long n = kb;
            __asm__ volatile("vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vmv.v.i v16, 0\n"
                             "vmv.v.i v18, 0\n"
                             "vsetvli t0, zero, e8, m1, ta, ma\n"
                             "1:\n"
                             "vle8.v v8, (%[a])\n"
                             "vle8.v v9, (%[b])\n"
                             "vle8.v v10, (%[b2])\n"
                             ".word 0xe294382b\n" /* vmadot v16, v8, v9 */
                             ".word 0xe2a4392b\n" /* vmadot v18, v8, v10 */
                             "addi %[a], %[a], 32\n"
                             "addi %[b], %[b], 32\n"
                             "addi %[b2], %[b2], 32\n"
                             "addi %[n], %[n], -1\n"
                             "bnez %[n], 1b\n"
                             "vsetvli t0, zero, e32, m2, ta, ma\n"
                             "vse32.v v16, (%[c])\n"
                             "vse32.v v18, (%[c2])\n"
                             : [a] "+r"(a), [b] "+r"(b), [b2] "+r"(b2), [n] "+r"(n)
                             : [c] "r"(tile), [c2] "r"(tile + 16)
                             : "t0", "v8", "v9", "v10", "v16", "v17", "v18", "v19", "memory");
            if (i * 4 + 4 <= M && j * 4 + 8 <= N)
            {
                for (int r = 0; r < 4; r++)
                {
                    int32_t *row = C + (long)(i * 4 + r) * N + j * 4;
                    memcpy(row, tile + r * 4, 16);
                    memcpy(row + 4, tile + 16 + r * 4, 16);
                }
                continue;
            }
            for (int h = 0; h < 2; h++)
                for (int r = 0; r < 4 && i * 4 + r < M; r++)
                    for (int c = 0; c < 4 && (j + h) * 4 + c < N; c++)
                        C[(long)(i * 4 + r) * N + (j + h) * 4 + c] = tile[h * 16 + r * 4 + c];
        }
}

/* One output row: dst[n] = clamp(requant(acc[n] + add[n] + row_add) + dst_off).
   Same arithmetic as arm_nn_requantize (generic C path): doubling high
   multiply with rounding, then rounding right shift (midpoint away from 0). */
static void ime_requant_row(const int32_t *acc, const int32_t *add, int32_t row_add, const int32_t *mult,
                            const int32_t *shift, int per_ch, int32_t dst_off, int32_t act_min,
                            int32_t act_max, int N, int8_t *dst)
{
    for (int n = 0; n < N;)
    {
        size_t vl = __riscv_vsetvl_e32m4(N - n);
        vint32m4_t v = __riscv_vadd_vx_i32m4(__riscv_vadd_vv_i32m4(__riscv_vle32_v_i32m4(acc + n, vl),
                                                                   __riscv_vle32_v_i32m4(add + n, vl), vl),
                                             row_add, vl);
        vint32m4_t m, sh;
        if (per_ch)
        {
            m = __riscv_vle32_v_i32m4(mult + n, vl);
            sh = __riscv_vle32_v_i32m4(shift + n, vl);
        }
        else
        {
            m = __riscv_vmv_v_x_i32m4(mult[0], vl);
            sh = __riscv_vmv_v_x_i32m4(shift[0], vl);
        }
        vint32m4_t lsh = __riscv_vmax_vx_i32m4(sh, 0, vl);
        vint32m4_t rsh = __riscv_vneg_v_i32m4(__riscv_vmin_vx_i32m4(sh, 0, vl), vl);
        v = __riscv_vsll_vv_i32m4(v, __riscv_vreinterpret_v_i32m4_u32m4(lsh), vl);
        vint64m8_t p = __riscv_vwmul_vv_i64m8(v, m, vl);
        p = __riscv_vadd_vx_i64m8(p, 1LL << 30, vl);
        v = __riscv_vnsra_wx_i32m4(p, 31, vl);
        vuint32m4_t ursh = __riscv_vreinterpret_v_i32m4_u32m4(rsh);
        vint32m4_t mask = __riscv_vsub_vx_i32m4(__riscv_vsll_vv_i32m4(__riscv_vmv_v_x_i32m4(1, vl), ursh, vl), 1, vl);
        vint32m4_t rem = __riscv_vand_vv_i32m4(v, mask, vl);
        vint32m4_t q = __riscv_vsra_vv_i32m4(v, ursh, vl);
        vint32m4_t thr = __riscv_vsra_vx_i32m4(mask, 1, vl);
        thr = __riscv_vadd_vx_i32m4_mu(__riscv_vmslt_vx_i32m4_b8(q, 0, vl), thr, thr, 1, vl);
        q = __riscv_vadd_vx_i32m4_mu(__riscv_vmsgt_vv_i32m4_b8(rem, thr, vl), q, q, 1, vl);
        q = __riscv_vadd_vx_i32m4(q, dst_off, vl);
        q = __riscv_vmin_vx_i32m4(__riscv_vmax_vx_i32m4(q, act_min, vl), act_max, vl);
        vint16m2_t h16 = __riscv_vncvt_x_x_w_i16m2(q, vl);
        __riscv_vse8_v_i8m1(dst + n, __riscv_vncvt_x_x_w_i8m1(h16, vl), vl);
        n += vl;
    }
}

/* dst[m * ldd + n] = clamp(requant(sum_k (A+a_off)(B+b_off) + bias[n]) + dst_off),
   per-channel (mult/shift arrays, per_ch=1) or per-tensor (per_ch=0). */
static void ime_fc_s8(const int8_t *A, int lda, int M, const int8_t *B, int N, int K,
                      int32_t a_off, int32_t b_off, const int32_t *bias,
                      const int32_t *mult, const int32_t *shift, int per_ch,
                      int32_t dst_off, int32_t act_min, int32_t act_max, int8_t *dst, int ldd)
{
    if ((size_t)M * N > ime_acc_cap)
    {
        free(ime_acc);
        ime_acc_cap = (size_t)M * N;
        ime_acc = (int32_t *)malloc(ime_acc_cap * sizeof(int32_t));
    }
    int32_t *acc = ime_acc;
    int32_t *add = (int32_t *)malloc((size_t)N * sizeof(int32_t));
    if ((long)M * N * K < IME_MIN_WORK)
    {
        /* Too small for tile packing to pay off: plain dot products. */
        for (int m = 0; m < M; m++)
            for (int n = 0; n < N; n++)
            {
                int32_t s = 0;
                const int8_t *a = A + (long)m * lda, *b = B + (long)n * K;
                for (int k = 0; k < K; k++)
                    s += a[k] * b[k];
                acc[(long)m * N + n] = s;
            }
        for (int n = 0; n < N; n++)
        {
            int32_t s = 0;
            for (int k = 0; k < K; k++)
                s += B[(long)n * K + k];
            add[n] = a_off * s + a_off * b_off * K + (bias ? bias[n] : 0);
        }
    }
    else
    {
        ime_gemm_s8(A, lda, M, B, N, K, acc);
        for (int n = 0; n < N; n++)
            add[n] = a_off * ime_bsum[n] + a_off * b_off * K + (bias ? bias[n] : 0);
    }
    for (int m = 0; m < M; m++)
    {
        int32_t asum = 0;
        if (b_off)
            for (int k = 0; k < K; k++)
                asum += A[(long)m * lda + k];
        ime_requant_row(acc + (long)m * N, add, b_off * asum, mult, shift, per_ch, dst_off, act_min, act_max, N,
                        dst + (long)m * ldd);
    }
    free(add);
}

/* Convolution as im2col + IME GEMM, one GEMM per group over all output pixels.
   Padding taps hold -input_offset so that (x + input_offset) is 0 there. */
static void ime_conv_s8(const cmsis_nn_conv_params *cp, const cmsis_nn_per_channel_quant_params *qp,
                        const cmsis_nn_dims *id, const int8_t *input, const cmsis_nn_dims *fd, const int8_t *filter,
                        const int32_t *bias, const cmsis_nn_dims *od, int8_t *output)
{
    const int32_t in_x = id->w, in_y = id->h, in_ch = id->c;
    const int32_t k_x = fd->w, k_y = fd->h, k_ch = fd->c;
    const int32_t out_x = od->w, out_y = od->h, out_ch = od->c;
    const int32_t groups = in_ch / k_ch, ocpg = out_ch / groups, cols = k_x * k_y * k_ch, rows = out_x * out_y;
    const int8_t pad = (int8_t)-cp->input_offset;
    int8_t *col = (int8_t *)malloc((size_t)rows * cols);
    for (int b = 0; b < id->n; b++)
    {
        const int8_t *in = input + (long)b * in_x * in_y * in_ch;
        int8_t *out = output + (long)b * rows * out_ch;
        for (int g = 0; g < groups; g++)
        {
            int8_t *p = col;
            for (int oy = 0; oy < out_y; oy++)
                for (int ox = 0; ox < out_x; ox++)
                    for (int ky = 0; ky < k_y; ky++)
                    {
                        const int32_t iy = oy * cp->stride.h - cp->padding.h + ky * cp->dilation.h;
                        for (int kx = 0; kx < k_x; kx++, p += k_ch)
                        {
                            const int32_t ix = ox * cp->stride.w - cp->padding.w + kx * cp->dilation.w;
                            if (iy < 0 || iy >= in_y || ix < 0 || ix >= in_x)
                                memset(p, pad, k_ch);
                            else
                                memcpy(p, in + ((long)iy * in_x + ix) * in_ch + g * k_ch, k_ch);
                        }
                    }
            ime_fc_s8(col, cols, rows, filter + (long)g * ocpg * cols, ocpg, cols, cp->input_offset, 0,
                      bias ? bias + g * ocpg : NULL, qp->multiplier + g * ocpg, qp->shift + g * ocpg, 1,
                      cp->output_offset, cp->activation.min, cp->activation.max, out + g * ocpg, out_ch);
        }
    }
    free(col);
}


static void ime_lstm_gate(const int32_t *ai, const int32_t *ah, const cmsis_nn_lstm_gate *g, int n_batch, int hidden,
                          int16_t *o)
{
    const int32_t *ebi = g->input_effective_bias, *ebh = g->hidden_effective_bias;
    for (int b = 0; b < n_batch; b++)
        for (int h = 0; h < hidden; h++)
        {
            long i = (long)b * hidden + h;
            int32_t r = arm_nn_requantize(ai[i] + ebi[h], g->input_multiplier, g->input_shift);
            r = CLAMP(r, NN_Q15_MAX, NN_Q15_MIN);
            if (ah)
            {
                int32_t r2 = arm_nn_requantize(ah[i] + ebh[h], g->hidden_multiplier, g->hidden_shift);
                r2 = CLAMP(r2, NN_Q15_MAX, NN_Q15_MIN);
                r = CLAMP(r + r2, NN_Q15_MAX, NN_Q15_MIN);
            }
            o[i] = (int16_t)r;
        }
    arm_nn_activation_s16(o, o, n_batch * hidden, 0, g->activation_type);
}

static void ime_lstm_time_major(const int8_t *input, int8_t *output, const cmsis_nn_lstm_params *p,
                                cmsis_nn_lstm_context *buffers)
{
    const int B = p->batch_size, T = p->time_steps, I = p->input_size, H = p->hidden_size;
    const cmsis_nn_lstm_gate *g[4] = {&p->forget_gate, &p->input_gate, &p->cell_gate, &p->output_gate};
    const long bh = (long)B * H, tbh = (long)T * bh;
    int32_t *xi = (int32_t *)malloc(4 * tbh * sizeof(int32_t));
    int32_t *hh = (int32_t *)malloc(4 * bh * sizeof(int32_t));
    int16_t *gt = (int16_t *)malloc(5 * bh * sizeof(int16_t));
    int16_t *tanh_c = gt + 4 * bh;
    int16_t *cell_state = (int16_t *)buffers->cell_state;
    for (int k = 0; k < 4; k++)
        ime_gemm_s8(input, I, T * B, (const int8_t *)g[k]->input_weights, H, I, xi + k * tbh);
    const int8_t *hidden_in = (const int8_t *)buffers->hidden_state;
    for (int t = 0; t < T; t++)
    {
        int8_t *hidden_out = output + t * bh;
        for (int k = 0; k < 4; k++)
        {
            if (hidden_in)
                ime_gemm_s8(hidden_in, H, B, (const int8_t *)g[k]->hidden_weights, H, H, hh + k * bh);
            ime_lstm_gate(xi + k * tbh + t * bh, hidden_in ? hh + k * bh : NULL, g[k], B, H, gt + k * bh);
        }
        arm_elementwise_mul_s16(gt, cell_state, 0, 0, cell_state, 0, p->forget_to_cell_multiplier,
                                p->forget_to_cell_shift, NN_Q15_MIN, NN_Q15_MAX, (int32_t)bh);
        arm_elementwise_mul_acc_s16(gt + bh, gt + 2 * bh, 0, 0, cell_state, 0, p->input_to_cell_multiplier,
                                    p->input_to_cell_shift, -p->cell_clip, p->cell_clip, (int32_t)bh);
        arm_nn_activation_s16(cell_state, tanh_c, (int32_t)bh, p->cell_scale_power + 12, ARM_TANH);
        arm_elementwise_mul_s16_s8(gt + 3 * bh, tanh_c, hidden_out, p->output_offset, p->output_multiplier,
                                   p->output_shift, H, B, 1);
        hidden_in = hidden_out;
    }
    if (buffers->hidden_state != NULL && T > 0)
        memcpy(buffers->hidden_state, hidden_in, bh);
    free(xi);
    free(hh);
    free(gt);
}

arm_cmsis_nn_status arm_lstm_unidirectional_s8(const int8_t *input,
                                               int8_t *output,
                                               const cmsis_nn_lstm_params *params,
                                               cmsis_nn_lstm_context *buffers)
{

    int8_t *hidden_in = (int8_t *)buffers->hidden_state;

    if (buffers->hidden_state == NULL)
    {
        memset(buffers->cell_state, 0, params->batch_size * params->hidden_size * sizeof(int16_t));
    }

    if (params->time_major)
    {
        ime_lstm_time_major(input, output, params, buffers);
    }
    else
    {

        cmsis_nn_lstm_params step_params = *params;
        step_params.batch_size = 1;

        for (int b = 0; b < params->batch_size; b++)
        {
            int8_t *step_hidden_in =
                (buffers->hidden_state != NULL) ? ((int8_t *)buffers->hidden_state + b * params->hidden_size) : NULL;

            cmsis_nn_lstm_context step_buffers = *buffers;
            step_buffers.cell_state = (int16_t *)buffers->cell_state + b * params->hidden_size;

            for (int t = 0; t < params->time_steps; t++)
            {
                const int8_t *data_in = input + (b * params->time_steps + t) * params->input_size;
                int8_t *hidden_out = output + (b * params->time_steps + t) * params->hidden_size;

                arm_cmsis_nn_status status =
                    arm_nn_lstm_step_s8(data_in, step_hidden_in, hidden_out, &step_params, &step_buffers, 1);

                if (status != ARM_CMSIS_NN_SUCCESS)
                {
                    return status;
                }

                step_hidden_in = hidden_out;
            }

            if (buffers->hidden_state != NULL && params->time_steps > 0)
            {
                memcpy((int8_t *)buffers->hidden_state + b * params->hidden_size,
                       step_hidden_in,
                       params->hidden_size * sizeof(int8_t));
            }
        }
    }
    return ARM_CMSIS_NN_SUCCESS;
}
